package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LoanRec struct {
	LrAcct      string
	LrPrincipal decimal.Decimal
	LrRate      decimal.Decimal
	LrYears     int64
}

var WsEofFlag string = "N"
var WsInterest decimal.Decimal = decimal.NewFromInt(0)
var WsTotal decimal.Decimal = decimal.NewFromInt(0)
var WsCount int64 = 0
var WsPrinEd string
var WsIntEd string
var WsTotalEd string

var loanFileScanner *bufio.Scanner
var loanFile *os.File
var currentLoanRec LoanRec
var inputDone bool

func formatEdited(val decimal.Decimal, picture string) string {
	// picture contains Z , . 9 characters
	// Determine scale = number of 9/Z after '.'
	// Determine integer digit placeholders count
	dotIdx := strings.Index(picture, ".")
	var intPartPic, fracPartPic string
	if dotIdx >= 0 {
		intPartPic = picture[:dotIdx]
		fracPartPic = picture[dotIdx+1:]
	} else {
		intPartPic = picture
		fracPartPic = ""
	}
	scale := 0
	for _, c := range fracPartPic {
		if c == '9' || c == 'Z' {
			scale++
		}
	}
	// Count digit placeholders in int part
	intDigits := 0
	for _, c := range intPartPic {
		if c == '9' || c == 'Z' {
			intDigits++
		}
	}

	// Truncate toward zero to scale (COBOL MOVE truncates? But values already have correct scale)
	// Ensure val has scale digits
	val = val.Truncate(int32(scale))

	// Get sign - all PICs unsigned, but handle negative just in case
	neg := val.IsNegative()
	if neg {
		val = val.Neg()
	}

	// Get integer and fractional parts as strings
	// Use string representation with scale digits
	s := val.StringFixed(int32(scale)) // e.g. "1234.50"
	var intStr, fracStr string
	if scale > 0 {
		parts := strings.SplitN(s, ".", 2)
		intStr = parts[0]
		if len(parts) > 1 {
			fracStr = parts[1]
		} else {
			fracStr = strings.Repeat("0", scale)
		}
		// Remove sign if present
		if strings.HasPrefix(intStr, "-") {
			intStr = intStr[1:]
		}
	} else {
		intStr = s
		if strings.HasPrefix(intStr, "-") {
			intStr = intStr[1:]
		}
		fracStr = ""
	}
	// High-order truncation: keep only low-order intDigits digits
	if len(intStr) > intDigits {
		intStr = intStr[len(intStr)-intDigits:]
	}
	// Left pad intStr with zeros to intDigits
	if len(intStr) < intDigits {
		intStr = strings.Repeat("0", intDigits-len(intStr)) + intStr
	}

	// Build edited integer part from right to left
	// picture int part length = len(intPartPic)
	resultInt := make([]byte, len(intPartPic))
	// digit index from rightmost digit placeholder
	digitIdx := len(intStr) - 1
	// Track if we have encountered a non-zero digit (for Z suppression)
	// Z suppression: leading zeros become spaces, and commas in suppressed zone become spaces
	// The rightmost 9 forces printing
	// Algorithm: scan placeholders from left to right? Easier: determine first non-zero position
	// Find position of first non-zero digit in intStr; if all zeros, then only last digit is significant
	firstNonZero := -1
	for i, ch := range intStr {
		if ch != '0' {
			firstNonZero = i
			break
		}
	}
	if firstNonZero == -1 {
		// all zeros -> significant only at last digit
		firstNonZero = len(intStr) - 1
	}

	for i := len(intPartPic) - 1; i >= 0; i-- {
		pc := intPartPic[i]
		if pc == ',' || pc == '.' {
			resultInt[i] = byte(pc)
		} else if pc == '9' || pc == 'Z' {
			if digitIdx >= 0 {
				d := intStr[digitIdx]
				isSignificant := digitIdx >= firstNonZero
				if pc == 'Z' && !isSignificant {
					// replace with space
					resultInt[i] = ' '
				} else {
					resultInt[i] = d
				}
				digitIdx--
			} else {
				// Should not happen due to padding
				if pc == 'Z' {
					resultInt[i] = ' '
				} else {
					resultInt[i] = '0'
				}
			}
		} else {
			resultInt[i] = byte(pc)
		}
	}
	// Now handle comma suppression: any comma that has only spaces to its left (ignoring) and spaces? Actually spec: commas inside suppressed zone also become spaces
	// The simple rule: if all digit placeholders to the left of comma are suppressed (spaces), comma becomes space
	// We have already Z->space, so we can scan left to right: if we encounter comma and no digit (0-9) has been output to its left, make it space
	seenDigit := false
	for i := 0; i < len(resultInt); i++ {
		c := resultInt[i]
		if c >= '0' && c <= '9' {
			seenDigit = true
		} else if c == ',' {
			if !seenDigit {
				resultInt[i] = ' '
			}
		}
	}

	if scale > 0 {
		// Build fractional part (always digits, no suppression)
		// fracPartPic may contain only 9s
		// fracStr already has scale digits
		return string(resultInt) + "." + fracStr
	}
	return string(resultInt)
}

func pic9Truncate(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	// Truncate toward zero to scale, then keep low-order digits
	v = v.Truncate(scale)
	// Apply overflow truncation for integer part
	// Keep low-order digits: equivalent to modulo 10^(intDigits) for integer part
	// Preserve fractional part
	if intDigits <= 0 {
		return v
	}
	// Separate integer and fractional
	coeff := decimal.NewFromInt(1).Shift(scale) // 10^scale
	// scaled = v * 10^scale truncated integer
	scaled := v.Mul(coeff).Truncate(0)
	// For overflow, we want scaled modulo 10^(intDigits+scale) keeping sign
	// Use integer arithmetic on scaled value
	modVal := decimal.NewFromInt(1).Shift(int32(intDigits + int(scale)))
	// Need signed modulo keeping low-order digits: for positive, scaled % modVal; for negative, similar
	if scaled.IsNegative() {
		abs := scaled.Abs()
		rem := abs.Mod(modVal)
		scaled = rem.Neg()
	} else {
		scaled = scaled.Mod(modVal)
	}
	return scaled.Div(coeff)
}

func mainPara() {
	var err error
	loanFile, err = os.Open("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			loanFileScanner = bufio.NewScanner(strings.NewReader(""))
		} else {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
	} else {
		loanFileScanner = bufio.NewScanner(loanFile)
		// Allow long lines
		buf := make([]byte, 0, 64*1024)
		loanFileScanner.Buffer(buf, 10*1024*1024)
	}
	readPara()
	for !inputDone {
		processPara()
	}
	if loanFile != nil {
		loanFile.Close()
	}
	summaryPara()
}

func readPara() {
	if loanFileScanner == nil || !loanFileScanner.Scan() {
		WsEofFlag = "Y"
		inputDone = true
		return
	}
	line := loanFileScanner.Text()
	if len(line) < 21 {
		line = line + strings.Repeat(" ", 21-len(line))
	}
	if len(line) > 21 {
		line = line[:21]
	}
	// Parse fields
	acct := line[0:6]
	prinStr := line[6 : 6+9]
	rateStr := line[15 : 15+4]
	yearsStr := line[19 : 19+2]

	// Parse principal 9(7)V99: 9 digits integer
	var prinVal decimal.Decimal
	{
		s := strings.TrimSpace(prinStr)
		if s == "" {
			s = "0"
		}
		// digits only; may contain spaces? treat spaces as zero? COBOL would expect digits
		// Remove non-digit just in case
		clean := ""
		for _, ch := range s {
			if ch >= '0' && ch <= '9' {
				clean += string(ch)
			}
		}
		if clean == "" {
			clean = "0"
		}
		n := decimal.RequireFromString(clean)
		prinVal = decimal.New(n.IntPart(), -2)
	}
	var rateVal decimal.Decimal
	{
		s := strings.TrimSpace(rateStr)
		if s == "" {
			s = "0"
		}
		clean := ""
		for _, ch := range s {
			if ch >= '0' && ch <= '9' {
				clean += string(ch)
			}
		}
		if clean == "" {
			clean = "0"
		}
		n := decimal.RequireFromString(clean)
		rateVal = decimal.New(n.IntPart(), -2)
	}
	var yearsVal int64
	{
		s := strings.TrimSpace(yearsStr)
		if s == "" {
			s = "0"
		}
		clean := ""
		for _, ch := range s {
			if ch >= '0' && ch <= '9' {
				clean += string(ch)
			}
		}
		if clean == "" {
			clean = "0"
		}
		var v int64
		fmt.Sscan(clean, &v)
		yearsVal = v
	}

	currentLoanRec = LoanRec{
		LrAcct:      acct,
		LrPrincipal: prinVal,
		LrRate:      rateVal,
		LrYears:     yearsVal,
	}
}

func processPara() {
	// COMPUTE WS-INTEREST ROUNDED = LR-PRINCIPAL * LR-RATE * LR-YEARS / 100
	yearsDec := decimal.NewFromInt(currentLoanRec.LrYears)
	prod := currentLoanRec.LrPrincipal.Mul(currentLoanRec.LrRate).Mul(yearsDec)
	quot := prod.Shift(-2) // divide by 100
	rounded := quot.Round(2)
	// Store into PIC 9(9)V99 truncated low-order
	WsInterest = pic9Truncate(rounded, 9, 2)

	// ADD WS-INTEREST TO WS-TOTAL
	WsTotal = WsTotal.Add(WsInterest)
	WsTotal = pic9Truncate(WsTotal, 11, 2)

	WsCount = WsCount + 1
	// Truncate count to 5 digits low-order (though not needed)
	if WsCount > 99999 {
		WsCount = WsCount % 100000
	}

	WsPrinEd = formatEdited(currentLoanRec.LrPrincipal, "Z,ZZZ,ZZ9.99")
	WsIntEd = formatEdited(WsInterest, "ZZZ,ZZZ,ZZ9.99")
	// DISPLAY LR-ACCT " " WS-PRIN-ED " " WS-INT-ED
	fmt.Printf("%s %s %s\n", currentLoanRec.LrAcct, WsPrinEd, WsIntEd)

	readPara()
}

func summaryPara() {
	WsTotalEd = formatEdited(WsTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	// DISPLAY "RECORDS: " WS-COUNT  -> PIC 9(5) zero padded 5 digits
	countStr := fmt.Sprintf("%05d", WsCount)
	fmt.Printf("RECORDS: %s\n", countStr)
	fmt.Printf("TOTAL INTEREST: %s\n", WsTotalEd)
}

func main() {
	mainPara()
}

